    { k: "腹満", w: "腹滿攣急し、之を按ずるに堅くして痛む（大䗪蟲丸の乾血）", src: "本文", koma: "198R", note: "大䗪虫丸" },
    { k: "腹力", lv: "充実", w: "腹滿攣急し按ずるに堅し（大䗪蟲丸）", src: "本文", koma: "198R", sure: false, note: "大䗪虫丸。虚羸甚しいが腹は堅い" }
